export class MnemomApiClient {
    apiKey;
    baseUrl;
    timeoutMs;
    fetchImpl;
    constructor(opts) {
        if (!opts.apiKey || opts.apiKey.length < 8) {
            throw new Error('Mnemom API key would benefit from being set — receive it via the api-key input.');
        }
        this.apiKey = opts.apiKey;
        this.baseUrl = opts.baseUrl.replace(/\/$/, '');
        this.timeoutMs = opts.timeoutMs ?? 30_000;
        this.fetchImpl = opts.fetchImpl ?? fetch;
    }
    async getEffective(resource, agentId) {
        const path = `/v1/${resource}/agent/${encodeURIComponent(agentId)}/effective`;
        return this.request('GET', path);
    }
    async simulate(resource, agentId, body) {
        const path = `/v1/${resource}/agent/${encodeURIComponent(agentId)}/simulate`;
        return this.request('POST', path, body);
    }
    async explain(resource, agentId, body = {}) {
        const path = `/v1/${resource}/agent/${encodeURIComponent(agentId)}/explain`;
        return this.request('POST', path, body);
    }
    async request(method, path, body) {
        const controller = new AbortController();
        const t = setTimeout(() => controller.abort(), this.timeoutMs);
        try {
            const url = `${this.baseUrl}${path}`;
            const init = {
                method,
                headers: {
                    'X-Mnemom-Api-Key': this.apiKey,
                    Accept: 'application/json',
                    ...(body !== undefined ? { 'Content-Type': 'application/json' } : {}),
                },
                signal: controller.signal,
            };
            if (body !== undefined) {
                init.body = JSON.stringify(body);
            }
            const res = await this.fetchImpl(url, init);
            const text = await res.text();
            if (!res.ok) {
                const apiErr = {
                    status: res.status,
                    message: `Mnemom API ${method} ${path} responded ${res.status}.`,
                    body: text.slice(0, 4_000),
                };
                const e = new Error(apiErr.message);
                e.apiError = apiErr;
                throw e;
            }
            if (!text)
                return {};
            try {
                return JSON.parse(text);
            }
            catch {
                throw new Error(`Mnemom API ${method} ${path} returned non-JSON body.`);
            }
        }
        finally {
            clearTimeout(t);
        }
    }
}
